Method.Implementation:

	 try{
		 do ##super()
		$$$TRACE("Connect to " _ ..ApplicationAddress)
		//set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mmi.CdrReadDOB).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))
		set ..objCdrTuxService = ##class(org.ihc.itf.cdr.mmi.CdrReadDOB).%New(..JavaGateway,..ApplicationAddress, ..TuxedoService, ..LogDirectory _"/" _$$$JobConfigName _".log", $$$ConfigTrace($$$JobConfigName))		
     	set status = ..CheckObject()
	}catch err{
		$$$LOGERROR("Exception while getting DOB: " _err.AsSystemError() _ " _ data: " _ err.Data _ "; code:" _ err.Code)
	    //set status=$$$ERROR(" Exception while initializing Tuxedo Service: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	    Set status = ##class(IHC.ITF.ITFCOMMON.Utility).RetryMsgError(..%ConfigName," Exception while getting DOB from CDR: "_err.AsSystemError()_"::"_err.Data_"::"_err.Code)
	}

	quit status

 #dim status as %Status	 
 set status = $$$OK
 $$$TRACE("Inside OnMessage method<" _ pRequest.StringValue _ ">")

 	 $$$TRACE("objCdrTuxService Object valid: "_$IsObject(..objCdrTuxService))

 try{

	 if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Op-Cdr-Demogr-Dsql-GETPATDOB", " GetPatientDOB failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
			return status
		}
 	}

	$$$TRACE("Object name: " _ ..objCdrTuxService.%ClassName(1))


	 		$$$TRACE(" Calling Cdr Dsql GetPatDob for the empi# .."_pRequest.mmiNumber) 				 				 					 				 		
	 		set pResponse=##class(Ens.StringResponse).%New()	
	 		Set pResponse.StringValue = ..objCdrTuxService.GetDOB(pRequest.mmiNumber)
	 		Set respData = pResponse.StringValue		 		
	 		$$$TRACE(" Call after the CdrReadDOB ...."_respData)		 				 		


 } catch err {		 	
       Set status = ..ExceptionHandler(err, "OnMessage")
 }

 $$$TRACE("OnMessage status: " _ status)	

 return status
